import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"이동과 조우","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Travel-and-Encounters.md","filePath":"rules/Travel-and-Encounters.md"}'),i={name:"rules/Travel-and-Encounters.md"};function o(n,a,s,c,d,h){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="이동과-조우" tabindex="-1">이동과 조우 <a class="header-anchor" href="#이동과-조우" aria-label="Permalink to &quot;이동과 조우&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-travel-encounters.svg?raw=true" alt="원정 이동과 조우의 아이소 판정"></p><p>4방향 이동 중 조우 확률과 유형을 위치·방향·시야에 따라 판단합니다.</p><h2 id="_4방향-행동" tabindex="-1">4방향 행동 <a class="header-anchor" href="#_4방향-행동" aria-label="Permalink to &quot;4방향 행동&quot;">​</a></h2><p>동, 서, 남, 북 네 방향만 사용합니다. 대각선 입력은 행동을 소비하지 않고 거부됩니다. 탐색과 전투가 같은 격자를 사용하므로 이동 감각과 거리 판단이 바뀌지 않습니다.</p><h2 id="이동-비용" tabindex="-1">이동 비용 <a class="header-anchor" href="#이동-비용" aria-label="Permalink to &quot;이동 비용&quot;">​</a></h2><p>기본 한 칸 비용에 다음 요소가 더해집니다.</p><ul><li>계단, 사다리, 승강기 같은 층 전환</li><li>부상, 통증, 피로와 과적</li><li>어둠, 침수, 잔해와 화재</li><li>적대 세력 통제와 통행권</li><li>파티 규모, 은밀 이동과 호위 대상</li></ul><h2 id="경로-계획" tabindex="-1">경로 계획 <a class="header-anchor" href="#경로-계획" aria-label="Permalink to &quot;경로 계획&quot;">​</a></h2><p>세계 지도에서는 노선, 환승과 봉쇄를 비교합니다. 역을 선택하면 동일한 세계 그래프에서 세부 격자를 펼칩니다. 막힌 연결은 사라지지 않고 원인, 위험도와 복구 조건을 보여 줍니다.</p><h2 id="조우-생성" tabindex="-1">조우 생성 <a class="header-anchor" href="#조우-생성" aria-label="Permalink to &quot;조우 생성&quot;">​</a></h2><p>조우는 캠페인 시드, 위치, 시간, 소음, 세력 통제, 최근 사건과 파티 상태에서 결정됩니다. 동일한 세계 상태와 명령이면 같은 조우가 생성되어야 합니다.</p><p>모든 조우가 전투로 이어지지 않습니다. 통행료 지불, 교섭, 수리, 의료, 정보 제공, 은신과 우회가 정식 해결 방법입니다.</p>',13)])])}const _=e(i,[["render",o]]);export{p as __pageData,_ as default};
